Assisted-by: Claude:claude-opus-4-6
Assisted-by: Codex:gpt-5-4
Signed-off-by: Michael Bommarito <michael.bommarito@gmail.com>
Acked-by: Namjae Jeon <linkinjeon@kernel.org>
Signed-off-by: Steve French <stfrench@microsoft.com>

Here is the root cause:
The bug stems from insufficient size validation of ACE entries in the `smb_check_perm_dacl()` function. The original code only checked that the remaining buffer (`aces_size`) could accommodate the ACE header (offset of `access_req`, 4 bytes) and that the declared `ace->size` did not exceed `aces_size`. However, it failed to ensure that `ace->size` is at least the minimum required for the full ACE structure (including `access_req` at offset 4 and the SID at offset 8). This allows an attacker with permissions to set a crafted DACL to declare an ACE with `ace->size == 4`, passing both checks, but then the code reads `ace->access_req` (OOB) and later `ace->sid` (OOB), causing an out-of-bounds read. Additionally, the lower loop lacked a check on `ace->sid.num_subauth`, allowing OOB access when `compare_sids()` dereferences the sub-authority array.

Here is the patch:

 int smb_check_perm_dacl(struct ksmbd_conn *conn, const struct path *path,
 			__le32 *pdaccess, int uid)
 {
 	struct mnt_idmap *idmap = mnt_idmap(path->mnt);
 	struct smb_ntsd *pntsd = NULL;
 	struct smb_acl *pdacl;
 	struct posix_acl *posix_acls;
 	int rc = 0, pntsd_size, acl_size, aces_size, pdacl_size;
 	unsigned int dacl_offset;
 	size_t dacl_struct_end;
 	struct smb_sid sid;
 	int granted = le32_to_cpu(*pdaccess & ~FILE_MAXIMAL_ACCESS_LE);
 	struct smb_ace *ace;
 	int i, found = 0;
 	unsigned int access_bits = 0;
 	struct smb_ace *others_ace = NULL;
 	struct posix_acl_entry *pa_entry;
 	unsigned int sid_type = SIDOWNER;
 	unsigned short ace_size;

 	ksmbd_debug(SMB, "check permission using windows acl\n");
 	pntsd_size = ksmbd_vfs_get_sd_xattr(conn, idmap,
 					    path->dentry, &pntsd);
 	if (pntsd_size <= 0 || !pntsd)
 		goto err_out;

 	dacl_offset = le32_to_cpu(pntsd->dacloffset);
 	if (!dacl_offset ||
 	    check_add_overflow(dacl_offset, sizeof(struct smb_acl), &dacl_struct_end) ||
 	    dacl_struct_end > (size_t)pntsd_size)
 		goto err_out;

 	pdacl = (struct smb_acl *)((char *)pntsd + le32_to_cpu(pntsd->dacloffset));
 	acl_size = pntsd_size - dacl_offset;
 	pdacl_size = le16_to_cpu(pdacl->size);

 	if (pdacl_size > acl_size || pdacl_size < sizeof(struct smb_acl))
 		goto err_out;

 	if (!pdacl->num_aces) {
 		if (!(pdacl_size - sizeof(struct smb_acl)) &&
 		    *pdaccess & ~(FILE_READ_CONTROL_LE | FILE_WRITE_DAC_LE)) {
 			rc = -EACCES;
 			goto err_out;
 		}
 		goto err_out;
 	}

 	if (*pdaccess & FILE_MAXIMAL_ACCESS_LE) {
 		granted = READ_CONTROL | WRITE_DAC | FILE_READ_ATTRIBUTES |
 			DELETE;

 		ace = (struct smb_ace *)((char *)pdacl + sizeof(struct smb_acl));
 		aces_size = acl_size - sizeof(struct smb_acl);
 		for (i = 0; i < le16_to_cpu(pdacl->num_aces); i++) {
-			if (offsetof(struct smb_ace, access_req) > aces_size)
+			if (offsetof(struct smb_ace, sid) +
+			    aces_size < CIFS_SID_BASE_SIZE)
 				break;
 			ace_size = le16_to_cpu(ace->size);
-			if (ace_size > aces_size)
+			if (ace_size > aces_size ||
+			    ace_size < offsetof(struct smb_ace, sid) +
+				       CIFS_SID_BASE_SIZE)
 				break;
 			aces_size -= ace_size;
 			granted |= le32_to_cpu(ace->access_req);
 			ace = (struct smb_ace *)((char *)ace + le16_to_cpu(ace->size));
 		}
 	}

 	if (!uid)
 		sid_type = SIDUNIX_USER;
 	id_to_sid(uid, sid_type, &sid);

 	ace = (struct smb_ace *)((char *)pdacl + sizeof(struct smb_acl));
 	aces_size = acl_size - sizeof(struct smb_acl);
 	for (i = 0; i < le16_to_cpu(pdacl->num_aces); i++) {
-		if (offsetof(struct smb_ace, access_req) > aces_size)
+		if (offsetof(struct smb_ace, sid) +
+		    aces_size < CIFS_SID_BASE_SIZE)
 			break;
 		ace_size = le16_to_cpu(ace->size);
-		if (ace_size > aces_size)
+		if (ace_size > aces_size ||
+		    ace_size < offsetof(struct smb_ace, sid) +
+			       CIFS_SID_BASE_SIZE)
 			break;
 		aces_size -= ace_size;

+		if (ace->sid.num_subauth > SID_MAX_SUB_AUTHORITIES)
+			break;
+
 		if (!compare_sids(&sid, &ace->sid) ||
 		    !compare_sids(&sid_unix_NFS_mode, &ace->sid)) {
 			found = 1;
 			break;
 		}
 		if (!compare_sids(&sid_everyone, &ace->sid))
 			others_ace = ace;

 		ace = (struct smb_ace *)((char *)ace + le16_to_cpu(ace->size));
 	}

 	if (*pdaccess & FILE_MAXIMAL_ACCESS_LE && found) {
 		granted = READ_CONTROL | WRITE_DAC | FILE_READ_ATTRIBUTES |
 			DELETE;

 		granted |= le32_to_cpu(ace->access_req);

 		if (!pdacl->num_aces)
 			granted = GENERIC_ALL_FLAGS;
 	}

 	if (IS_ENABLED(CONFIG_FS_POSIX_ACL)) {
 		posix_acls = get_inode_acl(d_inode(path->dentry), ACL_TYPE_ACCESS);
 		if (!IS_ERR_OR_NULL(posix_acls) && !found) {
 			unsigned int id = -1;

 			pa_entry = posix_acls->a_entries;
 			for (i = 0; i < posix_acls->a_count; i++, pa_entry++) {
 				if (pa_entry->e_tag == ACL_USER)
 					id = posix_acl_uid_translate(idmap, pa_entry);
 				else if (pa_entry->e_tag == ACL_GROUP)
 					id = posix_acl_gid_translate(idmap, pa_entry);
 				else
 					continue;

 				if (id == uid) {
 					mode_to_access_flags(pa_entry->e_perm,
 							     0777,
 							     &access_bits);
 					if (!access_bits)
 						access_bits =
 							SET_MINIMUM_RIGHTS;
 					posix_acl_release(posix_acls);
 					goto check_access_bits;
 				}
 			}
 		}
 		if (!IS_ERR_OR_NULL(posix_acls))
 			posix_acl_release(posix_acls);
 	}

 	if (!found) {
 		if (others_ace) {
 			ace = others_ace;
 		} else {
 			ksmbd_debug(SMB, "Can't find corresponding sid\n");
 			rc = -EACCES;
 			goto err_out;
 		}
 	}

 	switch (ace->type) {
 	case ACCESS_ALLOWED_ACE_TYPE:
 		access_bits = le32_to_cpu(ace->access_req);
 		break;
 	case ACCESS_DENIED_ACE_TYPE:
 	case ACCESS_DENIED_CALLBACK_ACE_TYPE:
 		access_bits = le32_to_cpu(~ace->access_req);
 		break;
 	}

 check_access_bits:
 	if (granted &
 	    ~(access_bits | FILE_READ_ATTRIBUTES | READ_CONTROL | WRITE_DAC | DELETE)) {
 		ksmbd_debug(SMB, "Access denied with winACL, granted : %x, access_req : %x\n",
 			    granted, le32_to_cpu(ace->access_req));
 		rc = -EACCES;
 		goto err_out;
 	}

 	*pdaccess = cpu_to_le32(granted);
 err_out:
 	kfree(pntsd);
 	return rc;
 }



